# -*- coding: utf-8 -*-
# W-2 事件扩充（+65）：阶段专属 30（学院/毕业/战争/终局，按时间窗自然门控）+ 通用 35；天赋协同隐藏链 ≥3
EVENTS_W2 = [
# ---- 阶段专属 · 学院（acad_，day 212-342）8 ----
{"id":"w2_acad_quiz","day":302,"cls":"奇遇","text":"学院的期末考核出了道怪题：把一枚银币扔进沸水里，问它沉底时在想什么。考场里一半人答不上来，只有图书馆常客的学生写下：它在想，自己曾是一块矿。阅卷的老教授看完，批了三个字——‘答得妙’。"},
{"id":"w2_acad_ghost","day":222,"cls":"奇遇","text":"深夜，学院禁书区的灯自己亮了。守夜的学长壮着胆子进去，看见一本书摊在桌上，翻到的那一页，写着一句批注：门不是用来防外人的，是用来防里面的人。书皮上没有名字，只压着一片干枯的羽毛。"},
{"id":"w2_acad_debate","day":232,"cls":"商机","text":"学院辩论赛的题目是‘知识该不该有价’。反方辩手引了句老话：书读多了，账就算不清了。正方言辞激烈，说知识是照亮黑暗的灯。台下坐着的教务长始终没笑——散场后，他把正反双方的稿子都要走了。"},
{"id":"w2_acad_scholar","day":302,"cls":"人祸","text":"费尔曼教授的助手忽然请辞，连夜收拾东西离开学院。据说他走前把一摞借阅记录烧了，灰烬里还剩半页，隐约能看见‘金秤’两个字。有人去问费尔曼，他只说：人各有志。"},
{"id":"w2_acad_cellar","day":312,"cls":"奇遇","text":"学院地窖翻修，工人砸开一面墙，发现墙里砌着一扇铁门，门环上挂着一把生锈的锁。没人记得这门是什么时候砌进去的。教务处的老文书看了一眼，脸色变了，只说：封回去，当没见过。"},
{"id":"w2_acad_spring","day":322,"cls":"奇遇","text":"学院后山的泉水忽然变甜了，连喝三天，失眠的学生都睡得踏实。老园丁说这是‘守门人泉’——三十年前故都沉没那年，这泉干了，今年又活了。他说这话时，声音压得很低。"},
{"id":"w2_acad_letter","day":332,"cls":"商机","text":"学院公告栏贴出一张收购启事：高价收购三十年前故都时期的旧课本。启事没落款，只画了一杆秤。有学生拿着祖父的旧书去卖，收货人验完货，多给了一倍的钱，说：这本里夹着的书签，值这个价。"},
{"id":"w2_acad_silence","day":342,"cls":"人祸","text":"学院新来了一位‘图书巡察’，说是奉了圣辉城的令，检查藏书。他查得很细，每本书都要翻到最后一页。图书管理员发现，他抄走了一个名单——借过禁书的人。名单上有三个名字，第二天，那三个人都被叫去了教务处。"},
# ---- 阶段专属 · 毕业（grad_，day 352-402）6 ----
{"id":"w2_grad_oath","day":352,"cls":"奇遇","text":"毕业典礼上，老校长领着全体毕业生宣誓：知识为灯，照己照人。轮到最后一个学生宣誓时，他忽然停了，问：要是灯照见的东西，不该被看见呢？礼堂安静了一瞬。老校长看着他，说：那就记住自己看见过。"},
{"id":"w2_grad_map","day":362,"cls":"商机","text":"毕业生们交换通讯地址，有人递给你一张旧地图，说是在图书馆夹层里找到的，画的是北境全图，标着几个红点。递给你的人说：我按这图走了三年，红点的地方，都有一扇打不开的门。送你了。"},
{"id":"w2_grad_ring","day":372,"cls":"奇遇","text":"毕业前夜，你收到一枚旧戒指，戒面磨得发亮，看不清花纹。附着的纸条写着：三十年前，一个毕业生把戒指押在当铺，再没回来赎。当铺老板说，要是遇见要去北境的毕业生，就把戒指给他——他认得路。"},
{"id":"w2_grad_leave","day":382,"cls":"人祸","text":"毕业当天，学院西门外停着一队黑甲骑兵，说是来接‘学院的故人’。他们接走了图书管理员——那个抄名单的人。马车走远时，管理员在车帘后回头看了一眼，眼神像在找人，又像在认路。"},
{"id":"w2_grad_torch","day":392,"cls":"天灾","text":"毕业那夜的篝火晚会，火堆忽然烧成蓝色。学生们退开，只有老校长站着没动，他看了半晌，说：这是故都的火，烧了三十年，终于有人把它带出来了。说完，他把手里的松枝丢进火里，火又变回金黄。"},
{"id":"w2_grad_tome","day":402,"cls":"奇遇","text":"你收拾行李时，发现行李里多了一本书，扉页写着：赠给要去远方的人。翻到最后一页，画着七枚铁牌，围成一圈，中间压着一杆秤。书页边缘有一行小字：找到第七枚的时候，回来。"},
# ---- 阶段专属 · 战争（war_，day 412-501）10 ----
{"id":"w2_war_whistle","day":412,"cls":"人祸","text":"北境大营连夜吹响号角，说是前线退了二十里。溃兵涌进第三哨，把哨所的存粮吃空了。老铁匠没赶人，他把铁砧搬出来，连夜打箭头——溃兵们歇了一夜，天亮时每人带了一把新箭头走了。"},
{"id":"w2_war_spy","day":422,"cls":"奇遇","text":"军需官抓到一个探子，从他鞋底搜出一张图，画的不是布防——是一座城的地下水道，出口标得清清楚楚，出口上面画着一杆秤。审讯官看不懂，把图收进档案。当晚，档案室起了火，图没了。"},
{"id":"w2_war_banner","day":432,"cls":"商机","text":"前线需要军旗，布商们接了订单。有个布商发现，订的旗子颜色不对——不是北境的蓝，是另一种更深的蓝，像故都旧旗的颜色。他留了个心眼，把布样藏了一角。夜里有人来敲门，问他那角布样在哪。"},
{"id":"w2_war_medicine","day":442,"cls":"奇遇","text":"战地医馆缺药，一个游方郎中送来三车药材，分文不取。他说：我这条命，是三十年前一个故都大夫捡回来的。医馆的人问他名字，他说：无名氏。留下药材，他走了，药车辙印一直往南，消失在雪里。"},
{"id":"w2_war_mutiny","day":452,"cls":"人祸","text":"前线军心浮动，有人传言主帅要弃守北境。夜里，三个营的兵聚在营门口，要个说法。督军提着灯出来，只说了一句话：第三哨还在，我们就在。兵们散了大半，剩下几个，天亮时看见督军一夜白了一半头发。"},
{"id":"w2_war_iron","day":462,"cls":"商机","text":"铁价又涨了。自由港的废铁被收空，连农具铁锅都熔了。收铁的商人戴着面具，只收‘旧铁’——三十年以上的一律加倍。有人把祖传的佩剑卖了，换回一袋银币，走时回头看了好几眼，像在跟谁道别。"},
{"id":"w2_war_snow","day":472,"cls":"天灾","text":"前线下了场百年不遇的大雪，一夜之间冻死战马三百匹。双方不约而同停战三日，各自埋马。雪地上，两边的兵隔着一里地对望，谁也没动。有人听见对面传来笛声——吹的是故都的老调子。"},
{"id":"w2_war_road","day":482,"cls":"奇遇","text":"战乱中，一条废弃的旧商道被人重新踩了出来，通往东境。走这条道的人都说，路边的界碑上画着记号——一杆秤，一个箭头。没人知道记号是谁画的，但跟着记号走的人，都没迷过路。"},
{"id":"w2_war_dead","day":492,"cls":"人祸","text":"战后清点，第三哨的阵亡名单里，有个名字被划掉了。守名册的老文书说：这个人没死，他活着回来了，只是不肯报名字。有人去问老铁匠，老铁匠敲着铁砧说：活着就好，叫什么名字，不重要。"},
{"id":"w2_war_oldflag","day":501,"cls":"奇遇","text":"战事稍歇，北境营地里升起一面旧旗——蓝底，绣着一杆金秤。老兵们看见，都站住了。年轻的兵问这是什么旗，没人答。直到一个瘸腿的老兵开口：这是故都的旗，三十年前，旗在，城就没丢。"},
# ---- 阶段专属 · 终局（final_，day 511-561）6 ----
{"id":"w2_final_quiet","day":511,"cls":"奇遇","text":"战后的第一个黎明，安静得不像话。第三哨的钟没人敲，自己响了——不多不少，七下。守钟的老卒听得脸色发白：这钟三十年没自己响过。他跪在钟下，念了一夜谁也听不懂的话。"},
{"id":"w2_final_iron","day":521,"cls":"商机","text":"战后重建，北境需要大量铁器。老铁匠的铺子订单排到了明年，他却只接一半，剩下的时间用来打一样东西——七枚铁牌。他谁也不给看，打一枚，锁进箱子里一枚。"},
{"id":"w2_final_bridge","day":531,"cls":"奇遇","text":"故都旧址的河上，有人架起一座新桥。架桥的是个老兵，他说：当年故都沉的时候，桥断了，过不去的人，都死在了河那边。现在桥架起来了，该回来的人，能回来了。桥桩上刻着一杆秤。"},
{"id":"w2_final_letter","day":541,"cls":"奇遇","text":"你收到一封没有署名的信，信纸是故都的老纸，边角发黄。信上只写着一句话：门还没开，但门缝里已经透光了。落款处画着一杆秤，秤盘里放着七枚铁牌。"},
{"id":"w2_final_dust","day":551,"cls":"天灾","text":"故都旧址上空，忽然落了一场灰——不是沙，是极细的灰，落在人身上，像旧纸烧过的味道。老人们说，这是故都的魂在认人。年轻人笑着拍掉灰，没人注意到，灰落在地上，排成了一行字：别开门。"},
{"id":"w2_final_scale","day":561,"cls":"奇遇","text":"夜里，你梦见一杆金秤，秤盘一头放着故都，一头放着深渊。秤针停在中线，不偏不倚。秤旁边坐着个老人，他没有脸，只有声音：秤不平，门不开。他重复了三遍，声音一次比一次轻，最后像一阵风，散了。"},
# ---- 通用 35（复用安全 day，主题与 W-1 错开）----
{"id":"w2_g_dog","day":42,"cls":"奇遇","text":"自由港码头来了一条老狗，浑身泥，蹲在货栈门口不走。它谁都不跟，只跟着搬货的苦力走，搬完一趟，坐在原地等。码头管事烦了，扔了根骨头，它闻了闻，没吃。夜里，货栈遭了贼，老狗狂吠，惊跑了贼——从那天起，没人再赶它。"},
{"id":"w2_g_ironbell","day":82,"cls":"奇遇","text":"铁门关的铁匠铺收了个学徒，学打铁，第一天就把锤子抡断了。师父没骂他，递了把新的：锤子断了，手艺没断。学徒攥着新锤子，眼泪在眼眶里转，硬是没掉。"},
{"id":"w2_g_bird","day":92,"cls":"奇遇","text":"你住的客栈檐下，燕子今年来得特别早，筑巢的泥里混着一根银白的羽毛。老板说这燕子在檐下住了十几年，头一回筑这么早的巢。他说：老人讲，燕子早来，是给要走的人送行。"},
{"id":"w2_g_trail","day":102,"cls":"奇遇","text":"雪原上，你发现一串脚印，很新，却只有去路，没有回路。脚印很轻，像是没踩实——有人说，这是‘空脚印’，是故都的人回来收东西，收完就走，不回头。你顺着脚印走了一段，脚印在一棵枯树下消失了。"},
{"id":"w2_g_coin","day":142,"cls":"奇遇","text":"酒馆伙计找零时，多找了你一枚铜板。你退回去，他愣住，说这铜板在钱箱里躺了三年，谁都往外拿，就没人往里退。他看了你半天，说：你这个人，能处。"},
{"id":"w2_g_mill","day":152,"cls":"商机","text":"东境的水磨坊翻修，磨盘的石头是从故都旧址拉来的，雕着旧纹。磨坊主说这磨盘磨出来的面，格外白。来往的客商都来买，一传十十传百，磨坊的订单排到了秋收。"},
{"id":"w2_g_teacher","day":162,"cls":"人祸","text":"铁门关的私塾先生病倒了，学生们轮班伺候。先生醒来第一句话是：书背到第几页了？学生答：第三册。先生点点头：那病好了一半。窗外，有人悄悄放下一袋米，没留名字。"},
{"id":"w2_g_snowman","day":172,"cls":"奇遇","text":"第三哨的孩子们堆了个雪人，给它插了把木剑，说它是‘守关大将军’。老铁匠路过，看了一会儿，回家打了把铁皮小剑，插在雪人腰上。孩子们高兴得满街跑。第二天雪人化了，铁皮小剑被老铁匠收走了——他说，剑不能陪雪化掉。"},
{"id":"w2_g_haggle","day":182,"cls":"奇遇","text":"集市上，一个老妇人卖菜，少收了你一枚铜板。你说给多了，她摆摆手：多了的，是给你的脚力钱——你从南头走到北头，专买我这摊，我认得你。她顿了顿，又说：这世道，认得人的人，越来越少了。"},
{"id":"w2_g_stone","day":222,"cls":"奇遇","text":"河滩上，你捡到一块圆润的石头，上面有一道天然的纹路，像一杆秤。收古董的说这值钱，你不卖。夜里，你把石头放在枕边，睡得格外沉——梦里有条河，河上有座桥，桥头站着个人，向你招了招手。"},
{"id":"w2_g_candle","day":232,"cls":"奇遇","text":"圣辉城的教堂里，一个老修士在点蜡烛，一支一支，点满整排。有人问他为谁点的，他说：为回不来的人。他数到第三十七支，停了：这一支，留给将来能回来的人。"},
{"id":"w2_g_river","day":302,"cls":"天灾","text":"银穗河涨水，冲出一截旧城墙，墙砖上刻着故都的纹样。沿岸的村子都来抢砖，说要砌自家的墙。有个老妇人不让：这是故都的墙，拆了，故都就真没了。她坐在墙边守了三天，没人敢动。"},
{"id":"w2_g_shop","day":312,"cls":"商机","text":"自由港新开了一家铺子，卖的全是旧物——旧表、旧书、旧工具。铺主说：东西旧了，故事没旧。有人花一枚铜板买走一把旧钥匙，第二天又回来，问：这钥匙，能开哪扇门？铺主笑：开了才知道。"},
{"id":"w2_g_bandit","day":322,"cls":"人祸","text":"官道上又出了劫匪，这回劫的是药材车。押车的伙计被打晕，醒来时，药材被搬得整整齐齐，还留了一袋铜板，附了张条：药我拿了，钱不够的，记我账上，名字——故都人。官府查了三天，没查到‘故都人’。"},
{"id":"w2_g_lamp","day":332,"cls":"奇遇","text":"夜里赶路，你看见一间亮着灯的木屋，屋里没人，桌上放着一盏油灯，灯下压着一张字条：灯是给走夜路的人留的，走的时候，添满油，把灯留下。你照做了。走出二里地回头，那盏灯还亮着，像颗钉在黑里的钉子。"},
{"id":"w2_g_horse","day":342,"cls":"奇遇","text":"一匹枣红马跟了商队两天，赶不走。商队老板想卖它，兽医说：这马有旧伤，是战马，退役的。老板叹口气：那留下吧，多一口草料的事。马像是听懂了，从此走在商队最前头，夜里还替人守夜。"},
{"id":"w2_g_ink","day":352,"cls":"商机","text":"承天城的墨价跌了——新到的墨，写出来的字发灰，没人要。老书生们反而买：发灰的字，像旧信，读起来有味道。有个书商专门收这种墨，说：世人爱新墨，懂字的人，爱旧灰。"},
{"id":"w2_g_rope","day":362,"cls":"奇遇","text":"码头的老船工送你一段旧缆绳，说：这是沉船上的绳子，泡了三十年海水，比新绳结实。你收下，没问为什么。他补了一句：沉船上的东西，带着旧船的记忆，能认出回家的路。"},
{"id":"w2_g_wind","day":372,"cls":"天灾","text":"西境又起了风，把一片旧营地的灰吹上了天。路过的人说，那片营地是三十年前故都撤军扎过的，风一吹，灰里能闻到铁锈味——像是当年没来得及收的兵器，还在风里等着。"},
{"id":"w2_g_bench","day":382,"cls":"奇遇","text":"自由港长街的尽头，多了一把新长椅，靠背上刻着一行小字：等一个人，等了三十年，还没等到。没人知道是谁刻的，也没人坐那把椅子——都怕占了等的人的位置。"},
{"id":"w2_g_tide","day":392,"cls":"天灾","text":"东境的海潮退得比往年远，露出海底一片旧城的顶。渔民们不敢靠近，只有个老渔夫划着船去了，绕了一圈回来，说：那是故都的旧港，泊位还认得船。他回来就病了，烧了三天，烧退了，人老了一截。"},
{"id":"w2_g_book","day":402,"cls":"奇遇","text":"旧书摊上，你翻到一本日记，字迹工整，记的是三十年前一个旅人的见闻。最后一页写着：今日过第三哨，铁匠铺的炉火烧得旺。炉边坐着个年轻人，说他在等一个说法。我没问他等什么——有些等，问不得。"},
{"id":"w2_g_bell2","day":412,"cls":"奇遇","text":"第三哨的铜钟，今早被人敲了三下，很轻，不像报时。守钟的老卒跑去看，钟下放着一枚铁牌，跟三十年前那批一模一样。他掂了掂，把铁牌收进怀里，谁也没告诉。"},
{"id":"w2_g_plough","day":422,"cls":"商机","text":"战后，北境的铁匠们开始打一种新犁，犁铧上铸着故都的老纹。农人们说：用这种犁翻出来的地，庄稼长得格外壮。老铁匠听了，只说了一句：不是犁好，是土记得旧主人。"},
{"id":"w2_g_lantern","day":432,"cls":"奇遇","text":"上元节，自由港放河灯。一个盲眼老妇人也放了一盏，有人问：你看不见，放给谁看？她说：放给走丢的人看，灯认得回家的路。河灯漂出很远，在转弯的地方，晃了晃，像有人接住了它。"},
{"id":"w2_g_anvil","day":442,"cls":"奇遇","text":"老铁匠夜里练锤，敲到第七十下，铁砧里忽然传出回音——不是铁的声音，是钟的声音。他停手，回音也停了。他再敲，回音又起。他敲了一夜，那回音，像是从地底下传上来的。"},
{"id":"w2_g_northstar","day":452,"cls":"奇遇","text":"北境的夜，北极星格外亮。老猎人指着星说：这颗星，三十年前叫‘守门星’，故都的人靠它认路。后来故都沉了，没人叫它守门星了。他说着，忽然停住：今晚，它好像又亮了三分。"},
{"id":"w2_g_bowl","day":462,"cls":"奇遇","text":"雪夜里，一个乞丐在破庙门口讨饭，你给了半个饼。他掰了一半还你：你也要赶路，留一半。他吃完饼，从怀里摸出一根铁钉：这钉子我捡的，打了三十年的铁才认得——是夹钢的，好铁。你收下，他笑：好铁配好人。"},
{"id":"w2_g_flag","day":472,"cls":"奇遇","text":"自由港商会换了新旗，旧的蓝旗收进库房。库房的老管事趁没人，把旧旗叠好，夹进一本旧账本里。他说：旗子会旧，账本会烂，可这旗子的颜色，故都人记得住。"},
{"id":"w2_g_water","day":482,"cls":"天灾","text":"银穗河上游的泉眼忽然涌出黑水，流了三天，又变清了。捞水样的人说，黑水里泡着铁锈味，像是从很深的地方翻上来的。河边的老人说：地底的东西在翻身，翻身的时候，先吐口气。"},
{"id":"w2_g_cart","day":492,"cls":"商机","text":"战后，北境的马车行生意红火——拉建材的、拉粮的、拉人的。车行老板却皱着眉：生意好是好事，可我这心里，总觉得是在给什么人搬家。他点着账本说：搬得完的东西，都不值钱。"},
{"id":"w2_g_lantern2","day":501,"cls":"奇遇","text":"圣辉城的老钟楼，钟摆忽然停了，停在了七点整。工匠们上去修，发现钟摆的轴里卡着一枚旧币——币面刻着一杆秤。他们把钱币取出来，钟又走了。没人敢问，那枚旧币是谁放进去的。"},
{"id":"w2_g_track","day":511,"cls":"奇遇","text":"雪原上，你再次看见那串‘空脚印’——去路清晰，回路全无。这次你跟着它走了很久，脚印停在一座废弃的界碑前。界碑上，有人新刻了一行小字：回来了。只有三个字，像是等了很多年才刻下的。"},
{"id":"w2_g_fire","day":521,"cls":"奇遇","text":"第三哨的炉火，今年冬天烧得特别旺。老铁匠说：火旺，是因为有人心里有事，火就替他烧。他没说谁有事，只把炉边那根鹿角柄的短刀，擦了又擦。"},
{"id":"w2_g_seed","day":531,"cls":"商机","text":"故都旧址的土里，长出一片野麦，长得比别处都好。农人们来收种，说这麦子有故都的血脉，种哪儿都能活。有人把麦种寄去北境，附了张条：故都的东西，终究是压不住的。"},
{"id":"w2_g_bridge2","day":541,"cls":"奇遇","text":"东境的老桥年久失修，官府要拆。桥头卖茶的老妇人不让，她说：这桥是故都人修的，桥墩里压着一杆秤，秤在，桥就在。官府不信，拆到桥墩，真挖出一杆铁秤——秤杆断了，秤砣还在。桥，没拆。"},
{"id":"w2_g_star","day":551,"cls":"奇遇","text":"夜里，你数了七颗星，排成一条线。老猎人顺着你的手指看，脸色一变：那叫‘七锁星’，故都的老人说，七星连成线的时候，门就开了。你问：什么门？他摇头：没人知道，只知道开了门的人，都再没回来。"},
]
